class InsufficientFunds(ValueError):
    pass


def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError(f"amount must be positive: {amount}")
    if amount > balance:
        raise InsufficientFunds(
            f"cannot take {amount} from {balance}"
        )
    return balance - amount

