import string
from collections import Counter


def clean_words(text):
    words = []
    for piece in text.lower().split():
        word = piece.strip(string.punctuation)
        if word:
            words.append(word)
    return words


def report(text, n):
    counts = Counter(clean_words(text))
    if not counts:
        return "no words"
    lines = [
        f"{word}: {count}"
        for word, count in counts.most_common(n)
    ]
    return "\n".join(lines)
